// SoOptimal Superpower Lead Analysis
const leadData = $input.item.json;

// Advanced Lead Scoring System
function advancedLeadScoring(data) {
  let totalScore = 0;
  let scoringBreakdown = {};

  // Project type scoring (35-40 points possible)
  const projectWeights = {
    'commercial': 35, 'multi-unit': 40, 'basement renovation': 30,
    'new construction': 25, 'repair work': 15, 'installation': 20
  };

  const projectType = (data.projectType || '').toLowerCase();
  Object.entries(projectWeights).forEach(([type, weight]) => {
    if (projectType.includes(type)) {
      totalScore += weight;
      scoringBreakdown.projectType = { type, weight };
    }
  });

  // Urgency indicators (25 points possible)
  const urgencyWeights = {
    'urgent': 25, 'asap': 20, 'this week': 20, 'this month': 15, 'next month': 10
  };

  const timeline = (data.timeline || '').toLowerCase();
  const description = (data.description || '').toLowerCase();
  const urgencyText = timeline + ' ' + description;

  Object.entries(urgencyWeights).forEach(([indicator, weight]) => {
    if (urgencyText.includes(indicator)) {
      totalScore += weight;
      scoringBreakdown.urgency = { indicator, weight };
    }
  });

  // Budget estimation (30 points possible)
  const sqft = parseInt(data.squareFootage) || 0;
  const estimatedBudget = sqft * 3; // $3/sqft rough estimate

  let budgetScore = 0;
  if (estimatedBudget > 10000) budgetScore = 30;
  else if (estimatedBudget > 5000) budgetScore = 25;
  else if (estimatedBudget > 2000) budgetScore = 20;
  else if (estimatedBudget > 1000) budgetScore = 15;
  else budgetScore = 5;

  totalScore += budgetScore;
  scoringBreakdown.budget = { estimated: estimatedBudget, score: budgetScore };

  // Location premium (15 points possible)
  const location = (data.location || '').toLowerCase();
  const locationPremiums = {
    'kitchener': 10, 'waterloo': 10, 'cambridge': 8, 'guelph': 8, 'toronto': 15
  };

  Object.entries(locationPremiums).forEach(([city, premium]) => {
    if (location.includes(city)) {
      totalScore += premium;
      scoringBreakdown.location = { city, premium };
    }
  });

  // Determine priority and actions
  let priority = 'low';
  let actions = ['email_follow_up'];
  let estimatedValue = '$500-1000';
  let responseTime = '4 hours';

  if (totalScore >= 60) {
    priority = 'urgent';
    actions = ['immediate_call', 'priority_sms', 'same_day_estimate'];
    estimatedValue = '$2000-5000+';
    responseTime = '15 minutes';
  } else if (totalScore >= 40) {
    priority = 'high';
    actions = ['call_within_hour', 'personalized_sms', 'next_day_estimate'];
    estimatedValue = '$1000-2500';
    responseTime = '1 hour';
  } else if (totalScore >= 25) {
    priority = 'medium';
    actions = ['call_within_4_hours', 'standard_sms'];
    estimatedValue = '$500-1500';
    responseTime = '4 hours';
  }

  return {
    ...data,
    totalScore,
    priority,
    estimatedValue,
    actions,
    responseTime,
    scoringBreakdown,
    timestamp: new Date().toISOString(),
    leadId: 'LEAD_' + Date.now()
  };
}

const analyzedLead = advancedLeadScoring(leadData);
return { json: analyzedLead };

